    code: "async function upsertWithVersion(doc, embedding) {\n  await vectorDb.upsert([{\n    id: doc.id,\n    vector: embedding,\n    metadata: {\n      text: doc.text,\n      embeddingModel: \"text-embedding-3-small\",\n      embeddingModelVersion: \"2024-01\", // track this explicitly\n    },\n  }]);\n}\n\n// Periodic canary check\nasync function checkEmbeddingDrift(canaryQueries) {\n  for (const { query, expectedDocId } of canaryQueries) {\n    const results = await retrieve(query, 3);\n    if (!results.some((r) => r.metadata.docId === expectedDocId)) {\n      alertOncall(`Embedding drift suspected for query: ${query}`);\n    }\n  }\n}",
